import { useMemo, useState, type ChangeEvent, type FormEvent, type ReactNode } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { Link, useLocation } from 'wouter';
import { ArrowRight, BarChart3, CalendarDays, Check, ChevronRight, Clock3, FileText, Filter, Headphones, ImagePlus, Leaf, MapPin, MessageCircle, PackageCheck, Phone, Plus, RefreshCw, Search, Send, ShieldCheck, ShoppingBasket, Sprout, Star, TrendingUp, Truck, Upload, X } from 'lucide-react';
import {
  getGetListingsQueryKey,
  getGetOrdersQueryKey,
  useCreateListing,
  useCreateOrder,
  useGetDashboardSummary,
  useGetListings,
  useGetMandiPrices,
  useGetOrders,
  useHealthCheck,
  useRequestOtp,
  useSendAiChat,
  useVerifyOtp,
  type AuthUser,
  type Listing,
  type Order,
} from '@workspace/api-client-react';
import { FarmAIShell, EmptyBlock, ErrorBlock, LoadingBlock, PageHeader } from '@/components/farmai-shell';
import { getCopy, languageNames, type Language } from '@/lib/i18n';

const userStorageKey = 'farmai-user';
const languageStorageKey = 'farmai-language';

export function readUser(): AuthUser | null {
  try {
    const raw = localStorage.getItem(userStorageKey);
    return raw ? JSON.parse(raw) as AuthUser : null;
  } catch { return null; }
}

export function getLanguage(): Language {
  const value = localStorage.getItem(languageStorageKey);
  return value === 'hi' || value === 'mr' ? value : 'en';
}

function formatMoney(value: number | string) {
  return `₹${Number(value).toLocaleString('en-IN')}`;
}

function Card({ children, className = '', ...props }: { children: ReactNode; className?: string; [key: string]: unknown }) {
  return <section className={`rounded-2xl border border-card-border bg-card shadow-sm ${className}`} {...props}>{children}</section>;
}

function StatusPill({ children, tone = 'green' }: { children: ReactNode; tone?: 'green' | 'amber' | 'blue' | 'muted' }) {
  const tones = { green: 'bg-primary/10 text-primary', amber: 'bg-accent/35 text-foreground', blue: 'bg-sky-100 text-sky-800', muted: 'bg-muted text-muted-foreground' };
  return <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.08em] ${tones[tone]}`}>{children}</span>;
}

function StatCard({ label, value, detail, tone, index }: { label: string; value: string; detail: string; tone: string; index: number }) {
  const accent = tone.includes('amber') ? 'bg-accent' : tone.includes('blue') ? 'bg-sky-400' : tone.includes('red') ? 'bg-rose-400' : 'bg-primary';
  return <div className={`rise-in stagger-${Math.min(index + 1, 5)} relative overflow-hidden rounded-2xl border border-card-border bg-card p-5 shadow-sm`} data-testid={`card-stat-${index}`}><div className={`absolute left-0 top-0 h-1 w-12 ${accent}`} /><p className="text-xs font-semibold text-muted-foreground">{label}</p><p className="mt-3 font-display text-3xl font-semibold tracking-tight">{value}</p><p className="mt-1 text-xs text-muted-foreground">{detail}</p></div>;
}

function SectionTitle({ title, action }: { title: string; action?: ReactNode }) {
  return <div className="mb-4 flex items-center justify-between gap-3"><h2 className="font-display text-xl font-semibold tracking-tight">{title}</h2>{action}</div>;
}

function Assistant({ language, role }: { language: Language; role: 'farmer' | 'buyer' }) {
  const t = getCopy(language);
  const [message, setMessage] = useState('');
  const [messages, setMessages] = useState<{ text: string; from: 'user' | 'ai' }[]>([]);
  const chat = useSendAiChat();
  function ask(event: FormEvent) {
    event.preventDefault();
    if (!message.trim() || chat.isPending) return;
    const text = message.trim();
    setMessages((current) => [...current, { text, from: 'user' }]);
    setMessage('');
    chat.mutate({ data: { message: text, language, role } }, { onSuccess: (response) => setMessages((current) => [...current, { text: response.reply, from: 'ai' }]) });
  }
  return <Card className="overflow-hidden border-primary/20 bg-primary text-primary-foreground"><div className="relative p-6 sm:p-7"><div className="absolute -right-8 -top-12 size-40 rounded-full border-[22px] border-accent/30" /><div className="relative"><div className="flex items-start justify-between"><div><StatusPill tone="amber"><MessageCircle size={12} /> FarmAI</StatusPill><h2 className="mt-4 max-w-md font-display text-2xl font-semibold leading-tight">{t.assistantTitle}</h2><p className="mt-2 text-sm text-primary-foreground/70">{role === 'farmer' ? t.assistantFarmerHint : t.assistantBuyerHint}</p></div><div className="grid size-11 place-items-center rounded-xl bg-primary-foreground/10"><Sprout size={23} /></div></div><form onSubmit={ask} className="mt-6 flex gap-2 rounded-xl bg-primary-foreground/10 p-1.5 focus-within:ring-2 focus-within:ring-accent"><input value={message} onChange={(event) => setMessage(event.target.value)} placeholder={t.assistantPrompt} className="min-w-0 flex-1 bg-transparent px-3 py-2 text-sm text-primary-foreground outline-none placeholder:text-primary-foreground/50" data-testid="input-assistant-message" /><button className="grid size-9 shrink-0 place-items-center rounded-lg bg-accent text-accent-foreground transition-transform hover:-translate-y-0.5 disabled:opacity-50" disabled={chat.isPending} aria-label={t.send} data-testid="button-send-assistant">{chat.isPending ? <span className="size-3 animate-pulse rounded-full bg-accent-foreground" /> : <Send size={16} />}</button></form>{messages.length > 0 && <div className="mt-4 space-y-2" data-testid="list-assistant-messages">{messages.slice(-3).map((item, index) => <div key={`${item.from}-${index}`} className={`rounded-lg px-3 py-2 text-xs ${item.from === 'user' ? 'ml-8 bg-primary-foreground/10' : 'mr-8 bg-accent text-accent-foreground'}`}>{item.text}</div>)}</div>}{chat.isError && <p className="mt-2 text-xs text-accent-foreground">{t.assistantError}</p>}</div></div></Card>;
}

function MandiTable({ language }: { language: Language }) {
  const t = getCopy(language);
  const prices = useGetMandiPrices({ limit: 6 });
  if (prices.isLoading) return <LoadingBlock label={t.loading} />;
  if (prices.isError) return <ErrorBlock label={t.error} language={language} onRetry={() => prices.refetch()} />;
  const rows = prices.data ?? [];
  return <Card className="overflow-hidden"><div className="flex items-center justify-between px-5 pt-5"><div><SectionTitle title={t.mandi} action={<StatusPill><span className="size-1.5 rounded-full bg-primary" />{t.live}</StatusPill>} /><p className="mt-[-10px] text-xs text-muted-foreground">{t.governmentMarketData}</p></div><Link href="/farmer" className="hidden text-xs font-bold text-primary hover:underline sm:block" data-testid="link-mandi-all">{t.seeAll} <ArrowRight className="ml-1 inline" size={13} /></Link></div>{rows.length === 0 ? <div className="px-5 pb-6 pt-4"><EmptyBlock title={t.noData} detail={t.mandiFeedUnavailable} /></div> : <div className="mt-4 overflow-x-auto"><table className="data-table w-full min-w-[650px]" data-testid="table-mandi-prices"><thead><tr><th>{t.commodityHeader}</th><th>{t.marketHeader}</th><th>{t.modalPrice}</th><th>{t.range}</th><th>{t.updated}</th></tr></thead><tbody>{rows.map((row, index) => <tr className="rise-in" style={{ animationDelay: `${index * 60}ms` }} key={row.id} data-testid={`row-mandi-${row.id}`}><td><div className="flex items-center gap-3"><span className="grid size-8 place-items-center rounded-lg bg-accent/35 text-primary"><Leaf size={15} /></span><div><p className="font-semibold">{row.commodity}</p><p className="text-xs text-muted-foreground">{row.variety}</p></div></div></td><td><p className="text-sm">{row.market}</p><p className="text-xs text-muted-foreground">{row.district}, {row.state}</p></td><td><strong className="font-mono text-sm">{formatMoney(row.modalPrice)}</strong><span className="ml-1 text-xs text-muted-foreground">{row.unit}</span></td><td className="font-mono text-xs text-muted-foreground">{formatMoney(row.minPrice)} – {formatMoney(row.maxPrice)}</td><td className="text-xs text-muted-foreground">{new Date(row.updatedAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}</td></tr>)}</tbody></table></div>}</Card>;
}

function TrendChart({ trend, language }: { trend: { month: string; current: number; previous: number }[]; language: Language }) {
  const t = getCopy(language);
  if (!trend.length) return <EmptyBlock title={t.trendWarming} detail={t.trendDetail} />;
  const max = Math.max(...trend.flatMap((point) => [point.current, point.previous]), 1);
  return <div className="flex h-48 items-end gap-2 border-b border-border px-1 pb-0 sm:gap-4" data-testid="chart-price-trend">{trend.map((point, index) => <div key={point.month} className="group flex h-full flex-1 flex-col justify-end gap-2"><div className="flex h-full items-end justify-center gap-1"><div className="w-2 rounded-t-md bg-primary/25 transition-all group-hover:bg-primary/45 sm:w-3" style={{ height: `${Math.max(10, (point.previous / max) * 100)}%` }} /><div className="w-2 rounded-t-md bg-primary transition-all group-hover:bg-primary/80 sm:w-3" style={{ height: `${Math.max(10, (point.current / max) * 100)}%` }} /></div><span className="text-center font-mono text-[10px] text-muted-foreground">{point.month}</span>{index === trend.length - 1 && <div className="absolute" />}</div>)}</div>;
}

export function FarmerDashboard({ user, language, setLanguage }: { user: AuthUser; language: Language; setLanguage: (language: Language) => void }) {
  const t = getCopy(language);
  const summary = useGetDashboardSummary({ role: 'farmer', language }, { query: { queryKey: ['/api/dashboard/summary', { role: 'farmer', language }] } });
  return <FarmAIShell user={user} language={language} setLanguage={setLanguage}><PageHeader eyebrow={t.farmerWorkspaceToday} title={`${t.goodMorning}, ${user.name || t.farmer}. ${t.farmerReady}`} description={t.todayValue} action={<Link href="/farmer/listings" className="inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-bold text-primary-foreground shadow-sm transition-transform hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-ring/40" data-testid="link-new-listing"><Plus size={17} /> {t.addListing}</Link>} />{summary.isLoading ? <LoadingBlock label={t.loading} /> : summary.isError ? <ErrorBlock label={t.error} language={language} onRetry={() => summary.refetch()} /> : <>{summary.data && <div className="mb-7 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{summary.data.stats.map((stat, index) => <StatCard key={`${stat.label}-${index}`} {...stat} index={index} />)}</div>}<div className="grid gap-6 xl:grid-cols-[1.55fr_1fr]"><MandiTable language={language} /><Card className="p-5"><SectionTitle title={t.priceMovement} action={<div className="flex items-center gap-2 text-[10px] text-muted-foreground"><span className="size-2 rounded-sm bg-primary" /> {t.thisYear} <span className="size-2 rounded-sm bg-primary/25" /> {t.lastYear}</div>} /><TrendChart trend={summary.data?.trend ?? []} language={language} /><div className="mt-4 flex items-center gap-2 text-xs text-primary"><TrendingUp size={14} /> {t.modalPriceHint}</div></Card></div><div className="mt-6 grid gap-6 xl:grid-cols-[1fr_1.25fr]"><Card className="p-5"><SectionTitle title={t.recentActivity} action={<Clock3 size={17} className="text-muted-foreground" />} />{summary.data?.activity?.length ? <div className="divide-y divide-border">{summary.data.activity.slice(0, 5).map((activity, index) => <div className="rise-in flex gap-3 py-4 first:pt-1" style={{ animationDelay: `${index * 70}ms` }} key={activity.id} data-testid={`activity-${activity.id}`}><div className="mt-0.5 grid size-8 shrink-0 place-items-center rounded-lg bg-muted text-primary">{activity.type.toLowerCase().includes('price') ? <BarChart3 size={15} /> : activity.type.toLowerCase().includes('order') ? <PackageCheck size={15} /> : <FileText size={15} />}</div><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{activity.title}</p><p className="mt-0.5 text-xs text-muted-foreground">{activity.detail}</p></div><time className="whitespace-nowrap text-[10px] text-muted-foreground">{activity.time}</time></div>)}</div> : <EmptyBlock title={t.noData} detail={t.listingEmptyDetail} />}</Card><Assistant language={language} role="farmer" /></div></>}</FarmAIShell>;
}

function PhotoField({ value, onChange, language }: { value: string; onChange: (value: string) => void; language: Language }) {
  const t = getCopy(language);
  function handleFile(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => onChange(String(reader.result));
    reader.readAsDataURL(file);
  }
  return <label className="group relative flex min-h-[150px] cursor-pointer items-center justify-center overflow-hidden rounded-xl border border-dashed border-input bg-muted/50 transition-colors hover:border-primary hover:bg-primary/5" data-testid="label-photo-upload">{value ? <><img src={value} alt={t.cropPreview} className="absolute inset-0 size-full object-cover" data-testid="img-photo-preview" /><span className="absolute inset-x-3 bottom-3 rounded-lg bg-foreground/75 px-3 py-2 text-center text-xs font-semibold text-background">{t.replacePhoto}</span></> : <div className="text-center"><div className="mx-auto mb-2 grid size-10 place-items-center rounded-xl bg-card text-primary shadow-sm"><ImagePlus size={19} /></div><p className="text-xs font-semibold">{t.addCropPhoto}</p><p className="mt-1 text-[11px] text-muted-foreground">{t.photoTrust}</p></div>}<input type="file" accept="image/*" className="sr-only" onChange={handleFile} data-testid="input-listing-photo" /></label>;
}

function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) {
  return <label className="block"><span className="mb-2 block text-xs font-bold text-foreground">{label}</span>{children}{hint && <span className="mt-1.5 block text-[11px] text-muted-foreground">{hint}</span>}</label>;
}

const inputClass = 'w-full rounded-xl border border-input bg-background px-3.5 py-3 text-sm outline-none transition-colors placeholder:text-muted-foreground/70 focus:border-primary focus:ring-2 focus:ring-ring/20';

export function FarmerListings({ user, language, setLanguage }: { user: AuthUser; language: Language; setLanguage: (language: Language) => void }) {
  const t = getCopy(language);
  const queryClient = useQueryClient();
  const listings = useGetListings({ role: 'farmer' });
  const create = useCreateListing();
  const [photoUrl, setPhotoUrl] = useState('');
  const [form, setForm] = useState({ commodity: '', category: 'Vegetables', grade: 'A', quantity: '', unit: 'kg', price: '', district: '', state: 'Maharashtra' });
  const [notice, setNotice] = useState('');
  const [paused, setPaused] = useState<Record<string, boolean>>({});
  function update(key: string, value: string) { setForm((current) => ({ ...current, [key]: value })); }
  function submit(event: FormEvent) {
    event.preventDefault();
    setNotice('');
    create.mutate({ data: { ...form, farmerName: user.name || 'FarmAI farmer', quantity: Number(form.quantity), unit: form.unit as 'kg' | 'quintal', price: Number(form.price), photoUrl: photoUrl || null } }, { onSuccess: () => { setNotice('Listing published. Buyers can now find your produce.'); setForm({ commodity: '', category: 'Vegetables', grade: 'A', quantity: '', unit: 'kg', price: '', district: '', state: 'Maharashtra' }); setPhotoUrl(''); queryClient.invalidateQueries({ queryKey: getGetListingsQueryKey({ role: 'farmer' }) }); } });
  }
  return <FarmAIShell user={user} language={language} setLanguage={setLanguage}><PageHeader eyebrow={`${t.farmerWorkspace} / ${t.inventory}`} title={t.sellFair} description={t.listingDetailsPrompt} /><div className="grid gap-7 xl:grid-cols-[minmax(0,1.05fr)_minmax(0,.95fr)]"><Card className="p-5 sm:p-7"><div className="mb-6 flex items-start justify-between"><div><h2 className="font-display text-xl font-semibold">{t.newCropListing}</h2><p className="mt-1 text-xs text-muted-foreground">{t.visibleToBuyers}</p></div><span className="grid size-10 place-items-center rounded-xl bg-accent/35 text-primary"><Upload size={18} /></span></div><form id="form-create-listing" onSubmit={submit} className="space-y-5" data-testid="form-create-listing"><div className="grid gap-5 sm:grid-cols-2"><Field label={t.cropName}><input required value={form.commodity} onChange={(e) => update('commodity', e.target.value)} placeholder="e.g. Onion, Wheat, Turmeric" className={inputClass} data-testid="input-listing-commodity" /></Field><Field label={t.category}><select value={form.category} onChange={(e) => update('category', e.target.value)} className={inputClass} data-testid="select-listing-category"><option value="Vegetables">{t.vegetables}</option><option value="Fruits">{t.fruits}</option><option value="Grains">{t.grains}</option><option value="Spices">{t.spices}</option><option value="Pulses">{t.pulses}</option></select></Field><Field label={t.grade}><select value={form.grade} onChange={(e) => update('grade', e.target.value)} className={inputClass} data-testid="select-listing-grade"><option>A</option><option>B</option><option value="Premium">{t.premium}</option><option value="Organic">{t.organic}</option></select></Field><Field label={t.quantity}><div className="flex gap-2"><input required min="1" type="number" value={form.quantity} onChange={(e) => update('quantity', e.target.value)} placeholder="0" className={inputClass} data-testid="input-listing-quantity" /><select value={form.unit} onChange={(e) => update('unit', e.target.value)} className="w-28 rounded-xl border border-input bg-background px-2 text-sm outline-none focus:border-primary" data-testid="select-listing-unit"><option value="kg">kg</option><option value="quintal">quintal</option></select></div></Field><Field label={t.expectedPrice} hint={t.useMandiPrice}><div className="relative"><span className="absolute left-3.5 top-3 text-sm text-muted-foreground">₹</span><input required min="1" type="number" value={form.price} onChange={(e) => update('price', e.target.value)} placeholder="0" className={`${inputClass} pl-8`} data-testid="input-listing-price" /></div></Field><Field label={t.district}><input required value={form.district} onChange={(e) => update('district', e.target.value)} placeholder="e.g. Nashik" className={inputClass} data-testid="input-listing-district" /></Field><Field label={t.state}><select value={form.state} onChange={(e) => update('state', e.target.value)} className={inputClass} data-testid="select-listing-state"><option>Maharashtra</option><option>Madhya Pradesh</option><option>Gujarat</option><option>Karnataka</option><option>Rajasthan</option></select></Field></div><Field label={t.photo}><PhotoField value={photoUrl} onChange={setPhotoUrl} language={language} /></Field>{notice && <div className="flex items-center gap-2 rounded-xl bg-primary/10 px-3 py-3 text-xs font-semibold text-primary" data-testid="status-listing-success"><Check size={16} /> {notice}</div>}{create.isError && <div className="rounded-xl bg-destructive/10 px-3 py-3 text-xs font-semibold text-destructive" data-testid="status-listing-error">{t.publishError}</div>}<button type="submit" disabled={create.isPending} className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3.5 text-sm font-bold text-primary-foreground transition-transform hover:-translate-y-0.5 disabled:cursor-wait disabled:opacity-60" data-testid="button-submit-listing">{create.isPending ? t.publishing : <><Plus size={17} /> {t.submit}</>}</button></form></Card><div><SectionTitle title={t.listings} action={<StatusPill tone="muted">{listings.data?.length ?? 0} {t.liveListings}</StatusPill>} />{listings.isLoading ? <LoadingBlock label={t.loadingListings} /> : listings.isError ? <ErrorBlock label={t.error} language={language} onRetry={() => listings.refetch()} /> : listings.data?.length ? <div className="space-y-3">{listings.data.map((listing, index) => <ListingRow key={listing.id} listing={listing} index={index} paused={!!paused[listing.id]} onToggle={() => setPaused((current) => ({ ...current, [listing.id]: !current[listing.id] }))} language={language} />)}</div> : <EmptyBlock title={t.firstListing} detail={t.listingEmptyDetail} action={<a href="#form-create-listing" className="text-xs font-bold text-primary hover:underline" data-testid="link-empty-add-listing">{t.startListing}</a>} />}</div></div></FarmAIShell>;
}

function ListingRow({ listing, index, paused, onToggle, language }: { listing: Listing; index: number; paused: boolean; onToggle: () => void; language: Language }) {
  const t = getCopy(language);
  return <Card className={`rise-in flex gap-3 p-3 ${paused ? 'opacity-60' : ''}`} style={{ animationDelay: `${index * 70}ms` }} data-testid={`card-listing-${listing.id}`}><div className="size-[72px] shrink-0 overflow-hidden rounded-xl bg-accent/25">{listing.photoUrl ? <img src={listing.photoUrl} alt={t.cropPreview} className="size-full object-cover" /> : <div className="grid size-full place-items-center text-primary"><Leaf size={25} /></div>}</div><div className="min-w-0 flex-1 py-0.5"><div className="flex items-start justify-between gap-2"><div><h3 className="font-display font-semibold">{listing.commodity}</h3><p className="mt-0.5 text-xs text-muted-foreground">{listing.grade} {t.grade.toLowerCase()} · {listing.quantity} {listing.unit}</p></div><StatusPill tone={paused ? 'muted' : 'green'}>{paused ? t.paused : listing.status || t.live}</StatusPill></div><div className="mt-3 flex items-center justify-between gap-2"><span className="font-mono text-sm font-bold">{formatMoney(listing.price)} <span className="font-sans text-[10px] font-normal text-muted-foreground">/ {listing.unit}</span></span><button onClick={onToggle} className="rounded-lg border border-border px-2.5 py-1.5 text-[10px] font-bold text-muted-foreground hover:border-primary hover:text-primary" data-testid={`button-toggle-listing-${listing.id}`}>{paused ? t.resume : t.pause}</button></div></div></Card>;
}

export function BuyerDashboard({ user, language, setLanguage }: { user: AuthUser; language: Language; setLanguage: (language: Language) => void }) {
  const t = getCopy(language);
  const queryClient = useQueryClient();
  const [search, setSearch] = useState('');
  const [district, setDistrict] = useState('');
  const [grade, setGrade] = useState('');
  const [maxPrice, setMaxPrice] = useState(8000);
  const [selected, setSelected] = useState<Listing | null>(null);
  const [sample, setSample] = useState(true);
  const [quantity, setQuantity] = useState('1');
  const [city, setCity] = useState('');
  const queryParams = useMemo(() => ({ role: 'buyer' as const, commodity: search || undefined, district: district || undefined, grade: grade || undefined, maxPrice }), [search, district, grade, maxPrice]);
  const listings = useGetListings(queryParams);
  const createOrder = useCreateOrder();
  function order(event: FormEvent) {
    event.preventDefault();
    if (!selected || !city) return;
    createOrder.mutate({ data: { listingId: selected.id, quantity: Number(quantity), isSample: sample, shippingCity: city } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetOrdersQueryKey() }); setSelected(null); setCity(''); } });
  }
  return <FarmAIShell user={user} language={language} setLanguage={setLanguage}><PageHeader eyebrow={`${t.buyer} / ${t.sourceLocally}`} title={t.buyerTitle} description={t.buyerDescription} action={<Link href="/buyer/orders" className="inline-flex items-center justify-center gap-2 rounded-xl border border-border bg-card px-4 py-3 text-sm font-bold transition-colors hover:border-primary hover:text-primary" data-testid="link-buyer-orders"><ShoppingBasket size={17} /> {t.orders}</Link>} /><div className="mb-7 rounded-2xl bg-sidebar p-4 text-sidebar-foreground shadow-md sm:p-5"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-accent text-accent-foreground"><MapPin size={19} /></div><div><p className="font-display font-semibold">{t.sourceLocally}</p><p className="text-xs text-sidebar-foreground/60">{t.buyerFilterHint}</p></div></div><div className="mt-4 grid gap-2 md:grid-cols-[1.4fr_1fr_1fr_auto]"><div className="relative"><Search size={16} className="absolute left-3.5 top-3.5 text-sidebar-foreground/45" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder={t.search} className="w-full rounded-xl border border-sidebar-border bg-sidebar-foreground/5 py-3 pl-10 pr-3 text-sm outline-none placeholder:text-sidebar-foreground/40 focus:border-accent" data-testid="input-buyer-search" /></div><input value={district} onChange={(e) => setDistrict(e.target.value)} placeholder={t.district} className="rounded-xl border border-sidebar-border bg-sidebar-foreground/5 px-3.5 py-3 text-sm outline-none placeholder:text-muted-foreground/70 focus:border-primary" data-testid="input-buyer-district" /><select value={grade} onChange={(e) => setGrade(e.target.value)} className="rounded-xl border border-sidebar-border bg-sidebar-foreground/5 px-3.5 py-3 text-sm text-sidebar-foreground/75 outline-none focus:border-accent" data-testid="select-buyer-grade"><option value="">{t.anyGrade}</option><option value="Grade A">Grade A</option><option value="Grade B">Grade B</option><option value="Grade C">Grade C</option></select><button onClick={() => { setSearch(''); setDistrict(''); setGrade(''); setMaxPrice(8000); }} className="rounded-xl border border-sidebar-border px-4 py-3 text-xs font-bold text-sidebar-foreground/75 hover:border-accent hover:text-accent" data-testid="button-clear-filters"><RefreshCw size={15} className="mr-1 inline" /> {t.clearFilters}</button></div><label className="mt-3 block text-xs font-semibold text-sidebar-foreground/75">{t.maximumPrice} <span className="font-mono text-accent">₹{maxPrice.toLocaleString('en-IN')}</span><input type="range" min="500" max="8000" step="250" value={maxPrice} onChange={(e) => setMaxPrice(Number(e.target.value))} className="mt-2 w-full accent-accent" data-testid="input-buyer-max-price" /></label></div><div className="mb-4 flex items-center justify-between"><div><h2 className="font-display text-xl font-semibold">{t.freshNearYou}</h2><p className="mt-1 text-xs text-muted-foreground">{listings.data?.length ?? 0} {t.listingsAvailable}</p></div><div className="hidden items-center gap-2 text-xs text-muted-foreground sm:flex"><Filter size={14} /> {t.sortedDistance}</div></div>{listings.isLoading ? <LoadingBlock label={t.findingListings} /> : listings.isError ? <ErrorBlock label={t.error} language={language} onRetry={() => listings.refetch()} /> : listings.data?.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{listings.data.map((listing, index) => <BuyerListingCard key={listing.id} listing={listing} index={index} onOrder={() => { setSelected(listing); setSample(true); }} language={language} />)}</div> : <EmptyBlock title={t.noHarvestsMatch} detail={t.noHarvestsDetail} action={<button onClick={() => { setSearch(''); setDistrict(''); setGrade(''); setMaxPrice(8000); }} className="rounded-lg bg-primary px-4 py-2 text-xs font-bold text-primary-foreground" data-testid="button-empty-clear">{t.clearFilters}</button>} />}{selected && <OrderSheet listing={selected} sample={sample} setSample={setSample} quantity={quantity} setQuantity={setQuantity} city={city} setCity={setCity} onClose={() => setSelected(null)} onSubmit={order} pending={createOrder.isPending} error={!!createOrder.isError} language={language} />}</FarmAIShell>;
}

function BuyerListingCard({ listing, index, onOrder, language }: { listing: Listing; index: number; onOrder: () => void; language: Language }) {
  const t = getCopy(language);
  return <Card className="rise-in overflow-hidden transition-transform duration-200 hover:-translate-y-1 hover:shadow-md" style={{ animationDelay: `${index * 70}ms` }} data-testid={`card-buyer-listing-${listing.id}`}><div className="relative h-36 overflow-hidden bg-accent/20">{listing.photoUrl ? <img src={listing.photoUrl} alt={listing.commodity} className="size-full object-cover" /> : <div className="grid size-full place-items-center text-primary/50"><Sprout size={42} strokeWidth={1.2} /></div>}<div className="absolute left-3 top-3"><StatusPill>{listing.distanceKm ? `${listing.distanceKm} km ${t.away}` : t.nearby}</StatusPill></div></div><div className="p-4"><div className="flex items-start justify-between gap-3"><div><h3 className="font-display text-lg font-semibold">{listing.commodity}</h3><p className="mt-0.5 text-xs text-muted-foreground">{listing.category} · {listing.grade} {t.grade.toLowerCase()}</p></div><div className="text-right"><p className="font-mono text-base font-bold text-primary">{formatMoney(listing.price)}</p><p className="text-[10px] text-muted-foreground">{t.per} {listing.unit}</p></div></div><div className="mt-4 flex items-center justify-between border-t border-border pt-3"><span className="flex items-center gap-1 text-xs text-muted-foreground"><MapPin size={13} /> {listing.district}, {listing.state}</span><span className="text-xs font-semibold">{listing.quantity} {listing.unit} {t.available}</span></div><button onClick={onOrder} className="mt-4 flex w-full items-center justify-center gap-2 rounded-xl bg-primary py-3 text-xs font-bold text-primary-foreground transition-transform hover:-translate-y-0.5" data-testid={`button-order-listing-${listing.id}`}>{t.requestSample} <ArrowRight size={14} /></button></div></Card>;
}

function OrderSheet({ listing, sample, setSample, quantity, setQuantity, city, setCity, onClose, onSubmit, pending, error, language }: { listing: Listing; sample: boolean; setSample: (value: boolean) => void; quantity: string; setQuantity: (value: string) => void; city: string; setCity: (value: string) => void; onClose: () => void; onSubmit: (event: FormEvent) => void; pending: boolean; error: boolean; language: Language }) {
  const t = getCopy(language);
  const productTotal = Number(listing.price) * (sample ? 1 : Number(quantity || 1));
  const shipping = sample ? 150 : Math.round(productTotal * 0.02);
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-foreground/35 p-0 backdrop-blur-sm sm:items-center sm:p-5" role="dialog" aria-modal="true" data-testid="dialog-order"><div className="w-full max-w-lg rounded-t-3xl border border-border bg-card p-5 shadow-lg sm:rounded-3xl sm:p-7"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] font-bold uppercase tracking-[.15em] text-primary">{t.fromFarm}</p><h2 className="mt-2 font-display text-2xl font-semibold">{listing.commodity}</h2><p className="mt-1 text-xs text-muted-foreground">{listing.grade} {t.grade.toLowerCase()} · {listing.district}, {listing.state}</p></div><button onClick={onClose} className="rounded-lg p-2 text-muted-foreground hover:bg-muted" aria-label={t.closeOrderDialog} data-testid="button-close-order"><X size={18} /></button></div><form onSubmit={onSubmit} className="mt-6 space-y-4"><div className="grid grid-cols-2 gap-2 rounded-xl bg-muted p-1"><button type="button" onClick={() => setSample(true)} className={`rounded-lg py-2.5 text-xs font-bold ${sample ? 'bg-card text-primary shadow-sm' : 'text-muted-foreground'}`} data-testid="button-order-sample">{t.sampleOrder} · 1 {listing.unit}</button><button type="button" onClick={() => setSample(false)} className={`rounded-lg py-2.5 text-xs font-bold ${!sample ? 'bg-card text-primary shadow-sm' : 'text-muted-foreground'}`} data-testid="button-order-full">{t.fullOrder}</button></div><Field label={t.quantity}><input type="number" min="1" required disabled={sample} value={sample ? '1' : quantity} onChange={(e) => setQuantity(e.target.value)} className={inputClass} data-testid="input-order-quantity" /></Field><Field label={t.shippingCity}><input required value={city} onChange={(e) => setCity(e.target.value)} placeholder={t.whereSend} className={inputClass} data-testid="input-order-city" /></Field>{error && <p className="rounded-lg bg-destructive/10 px-3 py-2 text-xs font-semibold text-destructive">{t.orderError}</p>}<div className="space-y-2 border-t border-border pt-4 text-xs"><div className="flex items-center justify-between text-muted-foreground"><span>{t.produce}</span><span className="font-mono">{formatMoney(productTotal)}</span></div><div className="flex items-center justify-between text-muted-foreground"><span>{t.shipping}</span><span className="font-mono">{formatMoney(shipping)}</span></div><div className="flex items-center justify-between pt-1"><span className="font-semibold">{t.estimatedTotal}</span><strong className="font-mono text-lg">{formatMoney(productTotal + shipping)}</strong></div></div><button disabled={pending} className="flex w-full items-center justify-center gap-2 rounded-xl bg-primary py-3.5 text-sm font-bold text-primary-foreground disabled:opacity-60" data-testid="button-submit-order">{pending ? t.placing : <>{sample ? t.requestSample : t.placeOrder} <ArrowRight size={16} /></>}</button></form></div></div>;
}

const orderSteps = ['Ordered', 'Dispatched', 'Out for Delivery', 'Delivered'];
function stepIndex(status: string) { const index = orderSteps.indexOf(status); return index < 0 ? 0 : index; }

export function BuyerOrders({ user, language, setLanguage }: { user: AuthUser; language: Language; setLanguage: (language: Language) => void }) {
  const t = getCopy(language);
  const orders = useGetOrders();
  const [reviewed, setReviewed] = useState<Record<string, boolean>>(() => { try { return JSON.parse(localStorage.getItem('farmai-reviews') || '{}'); } catch { return {}; } });
  function review(id: string) { const next = { ...reviewed, [id]: true }; setReviewed(next); localStorage.setItem('farmai-reviews', JSON.stringify(next)); }
  return <FarmAIShell user={user} language={language} setLanguage={setLanguage}><PageHeader eyebrow={t.ordersWorkspace} title={t.yourOrders} description={t.orderTrackingNote} />{orders.isLoading ? <LoadingBlock label={t.loadingOrders} /> : orders.isError ? <ErrorBlock label={t.error} language={language} onRetry={() => orders.refetch()} /> : orders.data?.length ? <div className="space-y-5">{orders.data.map((order, index) => <OrderCard key={order.id} order={order} index={index} reviewed={!!reviewed[order.id]} onReview={() => review(order.id)} language={language} />)}</div> : <EmptyBlock title={t.orderListWaiting} detail={t.orderListDetail} action={<Link href="/buyer" className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground" data-testid="link-empty-source">{t.findProduce} <ArrowRight size={14} /></Link>} />}</FarmAIShell>;
}

function OrderCard({ order, index, reviewed, onReview, language }: { order: Order; index: number; reviewed: boolean; onReview: () => void; language: Language }) {
  const t = getCopy(language);
  const localizedSteps = [t.ordered, t.dispatched, t.outForDelivery, t.delivered];
  const current = stepIndex(order.status);
  return <Card className="rise-in p-5 sm:p-6" style={{ animationDelay: `${index * 90}ms` }} data-testid={`card-order-${order.id}`}><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><div className="flex flex-wrap items-center gap-2"><StatusPill tone={order.status === 'Delivered' ? 'green' : 'amber'}>{localizedSteps[current]}</StatusPill>{order.isSample && <span className="text-[10px] font-bold uppercase tracking-[.08em] text-muted-foreground">{t.sampleLabel}</span>}</div><h2 className="mt-3 font-display text-xl font-semibold">{order.commodity}</h2><p className="mt-1 text-xs text-muted-foreground">{t.from} {order.farmerName} · {order.quantity} {t.unitLabel} · {t.to} {order.shippingCity}</p></div><div className="text-left sm:text-right"><p className="font-mono text-lg font-bold">{formatMoney(order.total)}</p><p className="mt-1 flex items-center gap-1 text-xs text-muted-foreground sm:justify-end"><CalendarDays size={13} /> {new Date(order.createdAt).toLocaleDateString(language === 'en' ? 'en-IN' : language === 'hi' ? 'hi-IN' : 'mr-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</p></div></div><div className="relative mt-8 grid grid-cols-4 gap-1">{localizedSteps.map((step, stepNumber) => <div className="relative text-center" key={step}><div className={`relative z-10 mx-auto grid size-8 place-items-center rounded-full border-4 border-card ${stepNumber <= current ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>{stepNumber < current ? <Check size={14} /> : stepNumber === 0 ? <FileText size={13} /> : stepNumber === 1 ? <Truck size={13} /> : stepNumber === 2 ? <Clock3 size={13} /> : <PackageCheck size={13} />}</div><p className={`mt-2 text-[10px] font-semibold ${stepNumber <= current ? 'text-primary' : 'text-muted-foreground'}`}>{step}</p>{stepNumber < localizedSteps.length - 1 && <span className={`absolute left-[calc(50%+15px)] right-[calc(-50%+15px)] top-4 h-0.5 ${stepNumber < current ? 'bg-primary' : 'bg-border'}`} />}</div>)}</div>{order.status === 'Delivered' && <div className="mt-6 flex flex-col justify-between gap-3 rounded-xl bg-accent/25 p-4 sm:flex-row sm:items-center"><div><p className="text-sm font-bold">{reviewed ? t.reviewThanks : t.howWasProduce}</p><p className="mt-1 text-xs text-muted-foreground">{reviewed ? t.reviewRecorded : t.reviewHelp}</p></div>{reviewed ? <span className="flex items-center gap-1 text-xs font-bold text-primary"><Star size={14} fill="currentColor" /> {t.reviewed}</span> : <button onClick={onReview} className="rounded-lg bg-primary px-3 py-2 text-xs font-bold text-primary-foreground" data-testid={`button-review-order-${order.id}`}>{t.leaveReview}</button>}</div>}</Card>;
}

export function SettingsPage({ user, language, setLanguage }: { user: AuthUser; language: Language; setLanguage: (language: Language) => void }) {
  const [, setLocation] = useLocation();
  const [name, setName] = useState(user.name || '');
  const [phone, setPhone] = useState(user.phone);
  const [saved, setSaved] = useState(false);
  function save(event: FormEvent) { event.preventDefault(); const next = { ...user, name, phone }; localStorage.setItem(userStorageKey, JSON.stringify(next)); setSaved(true); setTimeout(() => setSaved(false), 2400); }
  function signOut() { localStorage.removeItem(userStorageKey); setLocation('/'); }
  const t = getCopy(language);
  return <FarmAIShell user={{ ...user, name }} language={language} setLanguage={setLanguage}><PageHeader eyebrow={t.accountPreferences} title={t.makeFarmAI} description={t.profileDescription} /><div className="grid max-w-4xl gap-6 lg:grid-cols-[1fr_.72fr]"><Card className="p-5 sm:p-7"><div className="mb-7 flex items-center gap-4"><div className="grid size-14 place-items-center rounded-2xl bg-accent text-xl font-bold text-accent-foreground">{(name || phone).slice(0, 1).toUpperCase()}</div><div><h2 className="font-display text-xl font-semibold">{t.profile}</h2><p className="mt-1 text-xs text-muted-foreground">{t.profileVisible}</p></div></div><form onSubmit={save} className="space-y-5"><Field label={t.yourName}><input value={name} onChange={(e) => setName(e.target.value)} placeholder={t.enterYourName} className={inputClass} data-testid="input-settings-name" /></Field><Field label={t.phoneNumber}><div className="relative"><Phone size={16} className="absolute left-3.5 top-3.5 text-muted-foreground" /><input value={phone} onChange={(e) => setPhone(e.target.value)} className={`${inputClass} pl-10`} data-testid="input-settings-phone" /></div></Field><Field label={t.language}><select value={language} onChange={(e) => setLanguage(e.target.value as Language)} className={inputClass} data-testid="select-settings-language">{Object.entries(languageNames).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></Field>{saved && <div className="flex items-center gap-2 rounded-xl bg-primary/10 px-3 py-3 text-xs font-bold text-primary" data-testid="status-settings-saved"><Check size={16} /> {t.profileUpdated}</div>}<button className="rounded-xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground transition-transform hover:-translate-y-0.5" data-testid="button-save-settings">{t.save}</button></form></Card><div className="space-y-4"><Card className="p-5"><div className="flex items-start gap-3"><div className="grid size-9 place-items-center rounded-xl bg-primary/10 text-primary"><ShieldCheck size={18} /></div><div><h3 className="text-sm font-bold">{t.trustedMarket}</h3><p className="mt-1 text-xs leading-5 text-muted-foreground">{t.phoneSecure}</p></div></div></Card><Card className="p-5"><div className="flex items-start gap-3"><div className="grid size-9 place-items-center rounded-xl bg-accent/45 text-accent-foreground"><Headphones size={18} /></div><div><h3 className="text-sm font-bold">{t.support}</h3><p className="mt-1 text-xs leading-5 text-muted-foreground">{t.listingOrderSupport}</p><button className="mt-3 text-xs font-bold text-primary hover:underline" onClick={() => window.alert(t.supportPhone)} data-testid="button-contact-support">{t.contactSupport} <ChevronRight size={13} className="inline" /></button></div></div></Card><button onClick={signOut} className="flex w-full items-center justify-center gap-2 rounded-xl border border-destructive/30 bg-destructive/5 px-4 py-3 text-sm font-bold text-destructive transition-colors hover:bg-destructive/10" data-testid="button-settings-signout"><X size={16} /> {t.signOut}</button></div></div></FarmAIShell>;
}

export function AuthPage() {
  const [, setLocation] = useLocation();
  const health = useHealthCheck({ query: { queryKey: ['/api/healthz'] } });
  const [language, setLanguageState] = useState<Language>(getLanguage);
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [role, setRole] = useState<'farmer' | 'buyer'>('farmer');
  const [phone, setPhone] = useState('');
  const [name, setName] = useState('');
  const [otp, setOtp] = useState('');
  const [challengeId, setChallengeId] = useState('');
  const [demoOtp, setDemoOtp] = useState('');
  const [error, setError] = useState('');
  const t = getCopy(language);
  const request = useRequestOtp();
  const verify = useVerifyOtp();
  function setLanguage(value: Language) { setLanguageState(value); localStorage.setItem(languageStorageKey, value); }
  function requestCode(event: FormEvent) {
    event.preventDefault();
    setError('');
    if (phone.replace(/\D/g, '').length < 10) { setError(t.phoneValidation); return; }
    request.mutate({ data: { phone, role, name: mode === 'signup' ? name : null } }, { onSuccess: (result) => { setChallengeId(result.challengeId); setDemoOtp(result.demoOtp || '1234'); } , onError: () => setError(t.requestOtpError) });
  }
  function verifyCode(event: FormEvent) {
    event.preventDefault();
    setError('');
    verify.mutate({ data: { challengeId, phone, role, otp, name: mode === 'signup' ? name : null } }, { onSuccess: (user) => { const existing = readUser(); const nextUser = user.name.startsWith('New ') && existing?.phone === user.phone && existing.name ? { ...user, name: existing.name } : user; localStorage.setItem(userStorageKey, JSON.stringify(nextUser)); setLocation(nextUser.role === 'farmer' ? '/farmer' : '/buyer'); }, onError: () => setError(t.verifyOtpError) });
  }
  return <div className="texture min-h-[100dvh] bg-background"><div className="grid min-h-[100dvh] lg:grid-cols-[1.05fr_.95fr]"><div className="relative hidden overflow-hidden bg-sidebar p-10 text-sidebar-foreground lg:flex lg:flex-col lg:justify-between"><div className="absolute -right-24 top-20 size-80 rounded-full border-[46px] border-sidebar-primary/15" /><div className="absolute bottom-20 left-[-60px] size-52 rounded-full bg-sidebar-accent/20 blur-2xl" /><Link href="/" className="relative flex items-center gap-3" data-testid="link-auth-brand"><span className="grid size-11 place-items-center rounded-xl bg-sidebar-primary text-sidebar-primary-foreground"><Sprout size={23} /></span><span><strong className="font-display text-xl">FarmAI</strong><span className="block text-[10px] uppercase tracking-[.18em] text-sidebar-foreground/50">{t.marketLabel}</span></span></Link><div className="relative max-w-lg"><p className="mb-5 font-mono text-[10px] uppercase tracking-[.2em] text-sidebar-primary">{t.heroEyebrow}</p><h1 className="font-display text-6xl font-semibold leading-[.96] tracking-[-.06em]">{t.heroTitleOne}<br /><span className="text-sidebar-primary">{t.heroTitleTwo}</span><br />{t.heroTitleThree}</h1><p className="mt-6 max-w-sm text-base leading-7 text-sidebar-foreground/65">{t.heroDescription}</p><div className="mt-10 flex items-center gap-3 text-xs font-semibold text-sidebar-foreground/70"><span className="grid size-7 place-items-center rounded-full bg-sidebar-accent text-sidebar-foreground"><ShieldCheck size={14} /></span> {t.builtFor}</div></div><div className="relative flex items-center justify-between text-xs text-sidebar-foreground/45"><span>{t.heroFooter}</span><span className="flex items-center gap-1"><span className={`size-1.5 rounded-full ${health.isError ? 'bg-accent' : 'bg-sidebar-primary'}`} /> {health.isError ? t.offlineMode : t.marketOnline}</span></div></div><div className="flex flex-col px-5 py-6 sm:px-10 lg:px-16"><div className="flex items-center justify-between lg:justify-end"><Link href="/" className="flex items-center gap-2 lg:hidden" data-testid="link-mobile-auth-brand"><span className="grid size-9 place-items-center rounded-lg bg-primary text-primary-foreground"><Sprout size={18} /></span><strong className="font-display text-lg">FarmAI</strong></Link><div className="flex items-center gap-1 rounded-xl border border-border bg-card p-1">{Object.entries(languageNames).map(([value, label]) => <button key={value} onClick={() => setLanguage(value as Language)} className={`rounded-lg px-2.5 py-1.5 text-[11px] font-bold ${language === value ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-foreground'}`} data-testid={`button-language-${value}`}>{label}</button>)}</div></div><div className="mx-auto flex w-full max-w-[430px] flex-1 flex-col justify-center py-10"><div className="mb-8"><p className="mb-3 font-mono text-[10px] font-bold uppercase tracking-[.18em] text-primary">{t.welcome}</p><h2 className="font-display text-4xl font-semibold tracking-[-.045em]">{mode === 'login' ? t.comeBack : t.putDownRoots}</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">{mode === 'login' ? t.signInDescription : t.signupDescription}</p></div><div className="mb-6 grid grid-cols-2 rounded-xl bg-muted p-1"><button onClick={() => { setMode('login'); setChallengeId(''); }} className={`rounded-lg py-2.5 text-sm font-bold ${mode === 'login' ? 'bg-card text-primary shadow-sm' : 'text-muted-foreground'}`} data-testid="button-auth-login">{t.login}</button><button onClick={() => { setMode('signup'); setChallengeId(''); }} className={`rounded-lg py-2.5 text-sm font-bold ${mode === 'signup' ? 'bg-card text-primary shadow-sm' : 'text-muted-foreground'}`} data-testid="button-auth-signup">{t.createAccount}</button></div>{!challengeId ? <form onSubmit={requestCode} className="space-y-5" data-testid="form-request-otp">{mode === 'signup' && <Field label={t.yourName}><input required value={name} onChange={(e) => setName(e.target.value)} placeholder={role === 'farmer' ? t.farmerNamePlaceholder : t.buyerNamePlaceholder} className={inputClass} data-testid="input-auth-name" /></Field>}<Field label={t.iAm}><div className="grid grid-cols-2 gap-2">{(['farmer', 'buyer'] as const).map((item) => <button key={item} type="button" onClick={() => setRole(item)} className={`flex items-center gap-3 rounded-xl border px-3 py-3 text-left text-sm font-bold transition-colors ${role === item ? 'border-primary bg-primary/10 text-primary' : 'border-input bg-background text-muted-foreground hover:border-primary/40'}`} data-testid={`button-role-${item}`}><span className={`grid size-8 place-items-center rounded-lg ${role === item ? 'bg-primary text-primary-foreground' : 'bg-muted'}`}>{item === 'farmer' ? <Sprout size={16} /> : <ShoppingBasket size={16} />}</span>{item === 'farmer' ? t.farmer : t.buyer}</button>)}</div></Field><Field label={t.phoneNumber} hint={t.phoneHint}><div className="relative"><Phone size={16} className="absolute left-3.5 top-3.5 text-muted-foreground" /><input required type="tel" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder={t.mobilePlaceholder} className={`${inputClass} pl-10`} data-testid="input-auth-phone" /></div></Field><p className="rounded-lg bg-accent/25 px-3 py-2 text-xs font-bold text-foreground" data-testid="text-auth-demo-otp">{t.demoOtpLabel}</p>{error && <p className="rounded-lg bg-destructive/10 px-3 py-2 text-xs font-semibold text-destructive" data-testid="status-auth-error">{error}</p>}<button disabled={request.isPending} className="flex w-full items-center justify-center gap-2 rounded-xl bg-primary py-3.5 text-sm font-bold text-primary-foreground transition-transform hover:-translate-y-0.5 disabled:opacity-60" data-testid="button-request-otp">{request.isPending ? t.sendingCode : <>{t.sendSecureCode} <ArrowRight size={16} /></>}</button></form> : <form onSubmit={verifyCode} className="space-y-5" data-testid="form-verify-otp"><div className="rounded-xl bg-primary/10 p-4"><div className="flex items-start gap-3"><div className="grid size-8 place-items-center rounded-lg bg-primary text-primary-foreground"><Phone size={15} /></div><div><p className="text-sm font-bold">{t.codeSentTo} {phone}</p><p className="mt-1 text-xs text-muted-foreground">{t.enterFourDigit}</p><p className="mt-2 font-mono text-[11px] font-bold text-primary" data-testid="text-demo-otp">{t.demoOtpLabel}</p></div></div></div><Field label={t.oneTimeCode}><input required autoFocus inputMode="numeric" maxLength={4} value={otp} onChange={(e) => setOtp(e.target.value.replace(/\D/g, '').slice(0, 4))} placeholder="· · · ·" className={`${inputClass} text-center font-mono text-xl tracking-[.5em]`} data-testid="input-auth-otp" /></Field>{error && <p className="rounded-lg bg-destructive/10 px-3 py-2 text-xs font-semibold text-destructive" data-testid="status-auth-error">{error}</p>}<button disabled={verify.isPending || otp.length !== 4} className="flex w-full items-center justify-center gap-2 rounded-xl bg-primary py-3.5 text-sm font-bold text-primary-foreground transition-transform hover:-translate-y-0.5 disabled:opacity-60" data-testid="button-verify-otp">{verify.isPending ? t.checkingCode : <>{t.enterFarmAI} <ArrowRight size={16} /></>}</button><button type="button" onClick={() => { setChallengeId(''); setOtp(''); }} className="w-full text-center text-xs font-bold text-muted-foreground hover:text-primary" data-testid="button-change-phone">{t.differentNumber}</button></form>}<div className="mt-8 flex items-start gap-2 border-t border-border pt-5 text-[11px] leading-5 text-muted-foreground"><ShieldCheck size={15} className="mt-0.5 shrink-0 text-primary" /> {t.phonePrivacy}</div></div><p className="text-center text-[11px] text-muted-foreground">{t.terms}</p></div></div></div>;
}
